/**
 * @ingroup iface_zcr_color_management_output_v1
 * @struct zcr_color_management_output_v1_listener
 */
struct zcr_color_management_output_v1_listener {
	/**
	 * color space changed
	 *
	 * The color_space_changed event is sent whenever the color space
	 * of the output changed, followed by one wl_output.done event
	 * common to output events across all extensions.
	 *
	 * This is not an initial event.
	 */
	void (*color_space_changed)(void *data,
				    struct zcr_color_management_output_v1 *zcr_color_management_output_v1);
	/**
	 * output extended dynamic range
	 *
	 * This is both an initial event and sent whenever the value
	 * changed. When the value changed, this event is followed by one
	 * wl_output.done event common to output events across all
	 * extensions.
	 *
	 * The extended dynamic range value describes how much dynamic
	 * range is available relative to the SDR maximum white. EDR value
	 * is proportional to luminance, and the luminance of black is used
	 * as the zero level. A value of 1.0 means that the the display can
	 * not display anything brighter than SDR maximum white. A value of
	 * 3.0 means that the SDR maximum white is at one third of the
	 * highest luminance the display can produce.
	 *
	 * The absolute luminance of the SDR maximum white depends on the
	 * monitor capabilities, the viewing conditions and the viewer
	 * personal preferences. A such, it cannot be given a single value
	 * in cd/m². Compositors using HDR video modes should allow users
	 * to control the the SDR maximum white level which the output EDR
	 * value is calculated from.
	 *
	 * The SDR maximum white is a relative reference luminance that
	 * allows to tone-map content from different dynamic ranges into a
	 * single common dynamic range for display.
	 *
	 * The EDR value is multiplied by 1000 to produce the integer value
	 * carried by the protocol.
	 * @param value EDR value * 1000
	 */
	void (*extended_dynamic_range)(void *data,
				       struct zcr_color_management_output_v1 *zcr_color_management_output_v1,
				       uint32_t value);
};

/**
 * @ingroup iface_zcr_color_management_output_v1
 */
static inline int
zcr_color_management_output_v1_add_listener(struct zcr_color_management_output_v1 *zcr_color_management_output_v1,
					    const struct zcr_color_management_output_v1_listener *listener, void *data)
{
	return wl_proxy_add_listener((struct wl_proxy *) zcr_color_management_output_v1,
				     (void (**)(void)) listener, data);
}

