/**
 * @ingroup iface_zcr_color_management_surface_v1
 * render intent
 *
 *
 * Rendering intent allow the client to hint at how to perform color space
 * transformations.
 *
 * See the ICC specification for more details about rendering intent.
 */
enum zcr_color_management_surface_v1_render_intent {
	/**
	 * perceptual
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_PERCEPTUAL = 0,
	/**
	 * media-relative colorimetric
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_RELATIVE = 1,
	/**
	 * saturation
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_SATURATION = 2,
	/**
	 * ICC-absolute colorimetric
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ABSOLUTE = 3,
	/**
	 * media-relative colorimetric + black point compensation
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_RELATIVE_BPC = 4,
};
#endif /* ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ENUM */

#ifndef ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM
#define ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM
/**
 * @ingroup iface_zcr_color_management_surface_v1
 * alpha mode
 *
 * Specifies whether alpha is pre-multiplied into color channels or not.
 * If pre-multiplied, the linear alpha value is already multiplied with the
 * (non-linear) color channel code values in the color channels.
 */
enum zcr_color_management_surface_v1_alpha_mode {
	/**
	 * alpha is independent from color channels
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_STRAIGHT = 0,
	/**
	 * alpha is pre-multiplied into color channels
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_PREMULTIPLIED = 1,
};
#endif /* ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM */

/**
 * @ingroup iface_zcr_color_management_surface_v1
 * @struct zcr_color_management_surface_v1_listener
 */
struct zcr_color_management_surface_v1_listener {
	/**
	 * output for color optimization
	 *
	 * The preferred_color_space event is sent when the compositor
	 * determines or switches the output that implies the preferred
	 * color space. The preferred color space is the one which likely
	 * has the most performance and quality benefits if used by a
	 * client for its surface contents.
	 *
	 * The event does not carry a zcr_color_space_v1 but a wl_output
	 * object. The concrete zcr_color_space_v1 can be created by
	 * calling zcr_color_management_output_v1.get_color_space on the
	 * output and listening to
	 * zcr_color_management_output_v1.color_space_changed events.
	 *
	 * As clients may bind to the same global wl_output multiple times,
	 * this event is sent for each bound instance that matches the
	 * preferred color space output. If a client has not bound to the
	 * right wl_output global at all, this event is not sent.
	 *
	 * This is only a hint and clients can set any valid color space
	 * with set_color_space but there might be performance and color
	 * accuracy improvements by providing the surface in the preferred
	 * color space.
	 */
	void (*preferred_color_space)(void *data,
				      struct zcr_color_management_surface_v1 *zcr_color_management_surface_v1,
				      struct wl_output *output);
};

