/**
 * @ingroup iface_zcr_color_space_v1
 * @struct zcr_color_space_v1_listener
 */
struct zcr_color_space_v1_listener {
	/**
	 * ICC profile describing the color space
	 *
	 * This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * The icc argument provides a file descriptor to the client which
	 * can be memory-mapped to provide the ICC profile describing the
	 * color space. The fd must be mapped with MAP_PRIVATE and
	 * read-only by the client.
	 *
	 * Compositors should send this event always when information is
	 * requested. ICC profiles provide the common foundation which all
	 * color managed clients may rely on.
	 * @param icc ICC profile file descriptor
	 * @param icc_size ICC profile size, in bytes
	 */
	void (*icc_file)(void *data,
			 struct zcr_color_space_v1 *zcr_color_space_v1,
			 int32_t icc,
			 uint32_t icc_size);
	/**
	 * well-known names of a color space
	 *
	 * [Deprecated] This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * EOTF, chromaticity and whitepoint contain well-known names of
	 * those properties if available and unknown otherwise.
	 *
	 * Compositors should not assume that all clients can understand
	 * these names. The names are provided for client convenience. If a
	 * client understands the name triplet, it may ignore other
	 * information about the color space, the ICC profile for example.
	 * Use complete_names instead.
	 * @param eotf EOTF
	 * @param chromaticity chromaticity
	 * @param whitepoint whitepoint
	 */
	void (*names)(void *data,
		      struct zcr_color_space_v1 *zcr_color_space_v1,
		      uint32_t eotf,
		      uint32_t chromaticity,
		      uint32_t whitepoint);
	/**
	 * RGB primaries along with whitepoint defining color space
	 *
	 * [Deprecated] This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * The RGB primary value arguments along with the whitepoint value
	 * arguments and eotf can be used to define an arbitrary or custom
	 * color space.
	 *
	 * The eotf enum contains well known names of that property, but
	 * the compositor should not assume that all clients will
	 * understand those names. Use complete_params instead.
	 * @param eotf EOTF
	 * @param primary_r_x red primary X * 10000
	 * @param primary_r_y red primary Y * 10000
	 * @param primary_g_x green primary X * 10000
	 * @param primary_g_y green primary Y * 10000
	 * @param primary_b_x blue primary X * 10000
	 * @param primary_b_y blue primary Y * 10000
	 * @param white_point_x white point X * 10000
	 * @param white_point_y white point Y * 10000
	 */
	void (*params)(void *data,
		       struct zcr_color_space_v1 *zcr_color_space_v1,
		       uint32_t eotf,
		       uint32_t primary_r_x,
		       uint32_t primary_r_y,
		       uint32_t primary_g_x,
		       uint32_t primary_g_y,
		       uint32_t primary_b_x,
		       uint32_t primary_b_y,
		       uint32_t white_point_x,
		       uint32_t white_point_y);
	/**
	 * end of color space information
	 *
	 * This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * This signifies that all color space information events have been
	 * delivered for the object.
	 */
	void (*done)(void *data,
		     struct zcr_color_space_v1 *zcr_color_space_v1);
	/**
	 * well-known names of a color space
	 *
	 * This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * EOTF, chromaticity, matrix, range and whitepoint contain
	 * well-known names of those properties if available and unknown
	 * otherwise.
	 *
	 * Compositors should not assume that all clients can understand
	 * these names. The names are provided for client convenience. If a
	 * client understands the name triplet, it may ignore other
	 * information about the color space, the ICC profile for example.
	 * @param eotf EOTF
	 * @param chromaticity chromaticity
	 * @param whitepoint whitepoint
	 * @param matrix Color matrix
	 * @param range Color range
	 * @since 3
	 */
	void (*complete_names)(void *data,
			       struct zcr_color_space_v1 *zcr_color_space_v1,
			       uint32_t eotf,
			       uint32_t chromaticity,
			       uint32_t whitepoint,
			       uint32_t matrix,
			       uint32_t range);
	/**
	 * RGB primaries along with whitepoint defining color space
	 *
	 * This event may be sent only as a response to
	 * zcr_color_space_v1.get_information.
	 *
	 * The RGB primary value arguments along with the whitepoint value
	 * arguments and eotf can be used to define an arbitrary or custom
	 * color space.
	 *
	 * The eotf enum contains well known names of that property, but
	 * the compositor should not assume that all clients will
	 * understand those names.
	 * @param eotf EOTF
	 * @param matrix Color matrix
	 * @param range Color range
	 * @param primary_r_x red primary X * 10000
	 * @param primary_r_y red primary Y * 10000
	 * @param primary_g_x green primary X * 10000
	 * @param primary_g_y green primary Y * 10000
	 * @param primary_b_x blue primary X * 10000
	 * @param primary_b_y blue primary Y * 10000
	 * @param white_point_x white point X * 10000
	 * @param white_point_y white point Y * 10000
	 * @since 3
	 */
	void (*complete_params)(void *data,
				struct zcr_color_space_v1 *zcr_color_space_v1,
				uint32_t eotf,
				uint32_t matrix,
				uint32_t range,
				uint32_t primary_r_x,
				uint32_t primary_r_y,
				uint32_t primary_g_x,
				uint32_t primary_g_y,
				uint32_t primary_b_x,
				uint32_t primary_b_y,
				uint32_t white_point_x,
				uint32_t white_point_y);
};

